INSERT INTO `users` (`id`, `username`, `email`, `password`, `settings`, `bookmarks`, `favorites`) VALUES
(1, 'abdu', 'abdutuahir@gmail.com', 'abd94', '{"isDarkMode":true,"primaryColor":"#1677ff","arabicFontSize":28,"translationFontSize":14,"notificationsEnabled":false,"reminderTime":"08:00","defaultTranslationId":87,"defaultTafsirId":16}', '[{"id":"quote-8240","type":"quote","content":{"id":8240,"arabic_txt":"مَنْ أَحَبَّ السَّلَامَةَ فَلْيُؤْثِرِ الْفَقْرَ وَمَنْ أَحَبَّ الرَّاحَةَ فَلْيُؤْثِرِ الزُّهْدَ فِي الدُّنْيَا","english_txt":"One who loves security must prefer poverty [over wealth] and one who loves comfort must prefer abstinence from pleasures in this world","source":"غرر الحكم ودرر الكلم","topic":"في مدح الفقر"},"date":1768140900789},{"id":"ayah-37-25","type":"ayah","content":{"arabicText":"مَا لَكُمْ لَا تَنَاصَرُونَ","translationText":"Translation not yet available","verseNumber":25,"surahName":"As-Saffat","surahNumber":37},"date":1767465983228},{"id":"quote-8805","type":"quote","content":{"id":8805,"arabic_txt":"عَلَيْكَ بِمَكَارِمِ الْخِلَالِ وَاصْطِنَاعِ الرِّجَالِ فَإِنَّهُمَا يَقِيَانِ مَصَارِعَ السَّوْءِ وَيُوجِبَانِ الْجَلَالَةَ","english_txt":"Acquire noble traits and do good to the people, for indeed these two things protect one from falling into difficulties and lead to loftiness","source":"غرر الحكم ودرر الكلم","topic":"آثار الإحسان"},"date":1766567928164}]', '[{"id":"ayah-37-25","type":"ayah","content":{"arabicText":"مَا لَكُمْ لَا تَنَاصَرُونَ","translationText":"Translation not yet available","verseNumber":25,"surahName":"As-Saffat","surahNumber":37},"date":1767465980106},{"id":"quote-5702","type":"quote","content":{"id":5702,"arabic_txt":"سُوءُ الْخُلُقِ نَكَدُ الْعَيْشِ وَعَذَابُ النَّفْسِ","english_txt":"Bad character makes life bitter and is a torment for the soul","source":"غرر الحكم ودرر الكلم","topic":"سوء الخلق عذاب النفس"},"date":1766562349121}]'),
(2, 'Mehbub', 'mehbubkemal4391@gmail.com', 'meh123', '{"isDarkMode":false,"primaryColor":"#722ed1","arabicFontSize":28,"translationFontSize":14,"notificationsEnabled":false,"reminderTime":"08:00"}', '[{"id":"ayah-49-18","type":"ayah","content":{"arabicText":"إِنَّ ٱللَّهَ يَعْلَمُ غَيْبَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ بَصِيرٌۢ بِمَا تَعْمَلُونَ","translationText":"አላህ የሰማያትንና የምድርን ሩቅ ምሰጢር ያውቃል፤ አላህም የምትሰሩትን ሁሉ ተመልካች ነው፡፡","surahName":"Al-Hujurat","surahNumber":49,"verseNumber":"18"},"date":1766340728906}]', '[]');
